 s('drum-touch','북막 누르기','막 누르기 유무','같은 북·타격·거리','소리 지속 시간','누르지 않음',4,'손으로 누름',1,'초','막을 누르면 떨림도 빨리 줄었습니다.',[
 ['소리가 짧아진 원인은?','막의 진동이 빨리 줄었다','소리 높이가 반드시 높아졌다|공기가 모두 없어졌다|북 크기가 작아졌다','진동과 소리 지속이 함께 줄었어요.'],['막을 계속 자유롭게 두면?','이 조건에서는 더 오래 울릴 수 있다','반드시 더 높은 음이다|진동 없이 울린다|거리와 무관하게 같은 크기다','막 진동의 지속을 비교해요.'],['진동과 소리의 관련 근거는?','막 떨림과 소리가 함께 줄었다','북 색만 같았다|북 이름이 같았다|손을 댄 위치는 무관하다','원인 조작과 결과가 대응해요.']]);
 s('amplitude','같은 줄 세기','튕기는 세기','같은 줄·길이·팽팽함·거리','파형 진폭','약하게',2,'세게',6,'칸','같은 시간 반복 횟수는 두 조건 모두10회였습니다.',[
 ['B의 소리는 A보다 주로?','크게 들릴 수 있다','반드시 높은 음이다|반드시 낮은 음이다|진동이 느리다','진폭이 크기와 연결돼요.'],['반복 수를 그대로 두고 진폭만 줄이면?','높이는 비슷하고 크기가 줄 수 있다','높이만 올라간다|진동 수가 반드시 늘어난다|소리 전달이 불가능하다','크기와 높이는 별개예요.'],['높이가 같다는 판단 근거는?','같은 시간 반복 수가 같다','진폭이 다르다만으로 충분|B가 크니 높다|줄이 보이니 낮다','반복 빠르기를 비교해요.']]);
 s('frequency','반복 빠르기','진동 반복 수','같은 시간·진폭·거리','1초 반복 횟수','A줄',100,'B줄',200,'회','기록 장치가 같은1초를 관찰했습니다.',[
 ['더 높은 음으로 예상되는 것은?','B줄','A줄|진폭이 같으니 반드시 같은 높이|반복 수는 높이와 무관','빠른 진동이 높은 소리예요.'],['A의 반복 수를200으로 바꾸면?','높이가 B에 가까워질 수 있다','크기만 반드시 두 배다|높이는 변할 수 없다|전달 물질이 바뀐다','높이와 반복 빠르기를 연결해요.'],['B가 더 큰 소리라고 확정 못 하는 이유는?','반복 수는 크기보다 높이와 관련된다','반복 수가 없어서|파형 진폭은 항상 무관해서|B가 멀리 있어서','진폭 정보와 분리해요.']]);
 s('air','벨과 공기','용기 속 공기 양','벨 작동·용기·듣는 거리','바깥 소리 크기','공기 많음',8,'공기 적음',2,'눈금','벨의 진동은 두 조건에서 계속 확인됐습니다. 고체 경로 소리가 남을 수 있습니다.',[
 ['B에서 작아진 까닭은?','공기를 통한 전달이 줄었다','벨이 멈춘 것만 원인이다|빛이 줄어서다|기체는 전달에 필요 없다','발생은 유지하고 전달을 바꿨어요.'],['공기를 다시 넣으면?','전달되는 소리가 커질 수 있다','벨 진동이 반드시 사라진다|진공보다 더 작아야 한다|벨의 음높이가 무조건 두 배다','매질 공급의 영향을 예상해요.'],['벨 진동 확인이 필요한 이유는?','발생 중단과 전달 감소를 구별하려고','진동이면 진공도 공기와 같아서|공기는 벨을 항상 멈춰서|벨 색이 높이를 정해서','발생원 상태를 통제해요.']]);
 s('solid','책상 전달','귀와 책상 접촉','같은 두드림·위치·거리','들린 소리 크기','귀를 책상에 댐',7,'귀를 띄움',3,'눈금','같은 책상 한쪽을 약하게 두드린 가상 관찰입니다.',[
 ['A 결과가 보여 주는 것은?','고체도 진동을 전달할 수 있다','소리는 공기에서만 간다|책상이 귀까지 이동했다|두드림 없이 소리 났다','고체 경로가 추가돼요.'],['접촉을 끊으면 줄어들 수 있는 경로는?','책상을 통한 귀로의 전달','모든 공기 경로만|빛 경로만|두드림 발생 자체','경로를 구분해요.'],['재료별 전달을 비교하려면?','길이와 두드림 조건을 맞춘다','목재만 더 세게 두드린다|금속만 가까이 듣는다|거리 차이를 무시한다','재료 외 조건이 같아야 해요.']]);
 s('distance','소리와 거리','발생원에서 듣는 거리','같은 스피커·출력·공간','소리 크기','가까이',9,'멀리',4,'눈금','스피커 설정과 음높이는 바꾸지 않았습니다.',[
 ['B가 작아진 해석은?','듣는 거리가 크기에 영향을 주었다','스피커 진동수가 반드시 감소했다|전달 매질이 전부 없어졌다|큰 소리는 항상 높다','출력 고정의 거리 비교예요.'],['출력을 유지하고 더 가까이 오면?','더 크게 들릴 수 있다','반드시 높은 음이 된다|진동 수가0이 된다|소리는 발생 안 한다','거리와 크기를 연결해요.'],['발생 진폭 감소로 확정 못 하는 근거는?','출력은 같고 듣는 거리만 달랐다','B값이 더 작다는 사실만|스피커가 보였다는 사실만|같은 노래라는 이름만','관찰 위치와 발생 조건을 구분해요.']]);
 s('string-length','줄의 길이','진동하는 줄 길이','재질·굵기·팽팽함·튕김','1초 반복 수','긴 줄',120,'짧은 줄',240,'회','같은 줄의 눌러 고정한 위치만 바꿨습니다.',[
 ['짧은 줄의 음높이는?','더 높다','더 낮다|반복 수가 다르나 높이는 반드시 같다|무조건 더 크다','더 빠르게 진동했어요.'],['긴 줄 쪽의 진동 부분을 짧게 하면?','높은 음 쪽으로 바뀔 수 있다','항상 소리가 사라진다|반드시 낮아진다|팽팽함과 무관하게 크기만 변한다','이 비교 조건의 경향을 적용해요.'],['길이 효과를 해석할 근거는?','재질과 팽팽함을 같게 뒀다','반복 수가 크니 질량이 크다|두 줄 색만 같았다|길이는 진동과 무관하다','다른 높이 요인을 통제했어요.']]);
 s('tension','줄의 팽팽함','줄의 팽팽함','같은 길이·재질·굵기','반복 횟수','느슨함',90,'팽팽함',150,'회/초','끊어지지 않는 범위의 가상 줄입니다.',[
 ['B의 음높이가 높은 까닭은?','같은 시간 더 많이 진동한다','진폭이 반드시 더 커서|전달 거리가 짧아서|줄 길이가 길어져서','관찰 반복 수로 판단해요.'],['팽팽함 효과만 재검사하려면?','줄 길이를 유지한다','팽팽한 쪽만 길이도 줄인다|재질까지 바꾼다|듣는 거리를 같게 할 필요 없다','다른 변인을 통제해요.'],['큰 소리 여부는 왜 별도 정보가 필요한가?','반복 빠르기만으로 진폭을 알 수 없다','높은 소리는 반드시 작아서|낮은 소리는 반드시 커서|모든 소리는 같은 크기라서','높이와 크기를 구분해요.']]);
 s('mute','소리 줄이는 덮개','덮개 유무','스피커 출력·거리·공간','밖에서 잰 소리 크기','덮개 없음',10,'덮개 있음',4,'눈금','스피커 진동은 그대로였고 흡음 덮개를 씌웠습니다.',[
 ['덮개의 효과는?','밖으로 전달되는 소리를 줄였다','소리를 전혀 발생 못 하게 했다|음높이를 반드시 높였다|모든 진동을0으로 만들었다','발생과 전달을 구분해요.'],['덮개 재료를 비교할 때는?','두께와 측정 위치를 맞춘다','좋은 재료만 두껍게 쓴다|출력도 함께 바꾼다|한쪽만 귀를 가까이 댄다','공정한 재료 비교예요.'],['B에서도4가 기록된 사실은?','완전히 차단한 것은 아니다','덮개가 아무 효과도 없다|전달은 오직 진공에서 된다|모든 소리가 완전히 소멸했다','감소와 완전 차단은 달라요.']]);
