 s('compress','기체 압축','주사기 부피','밀폐·같은 공기 양·온도','누르는 힘','큰 부피',2,'작은 부피',7,'눈금','천천히 누르고 기체가 새지 않았습니다.',[
 ['작은 부피의 입자 모형은?','입자 수는 같고 평균 간격이 작다','입자 수가 줄었다|입자 자체가 작아졌다|기체가 없어졌다','밀폐 압축이에요.'],['손을 놓고 움직일 수 있게 하면?','팽창하는 쪽으로 움직일 수 있다','입자가 모두 사라진다|항상 더 작아진다|기체가 반드시 고체다','기체의 저항과 팽창을 연결해요.'],['힘 증가가 기체 부재를 뜻하지 않는 이유는?','갇힌 공기가 저항을 보였다','빈 공간이면 언제나 큰 힘이다|공기는 질량이 없기 때문|눈에 안 보이면 없는 것이기 때문','보이지 않는 물질의 작용이에요.']]);
 s('open-closed','주사기 입구','입구 상태','같은 주사기·출발 부피·누름','같은 위치까지 미는 힘','닫음',8,'열음',2,'눈금','열린 경우 공기가 밖으로 나갈 수 있습니다.',[
 ['A가 더 힘든 이유는?','갇힌 기체가 압축되며 저항한다','플라스틱이 반드시 다른 재료다|열린 곳에 공기가 전혀 없다|공기는 힘을 못 준다','탈출 경로 차이예요.'],['닫힌 입구를 열면?','공기가 빠져나가 누르기 쉬워질 수 있다','입자 자체가 작아진다|새 공기가 무한 생성된다|저항은 반드시 더 커진다','기체 양 변화도 가능해요.'],['두 조건 입자 수를 같다고 유지하면 틀린 이유는?','열린 경우 밖으로 나갈 수 있다','기체는 항상 입자가 없어서|주사기는 전부 고체라서|부피 단위가 달라서','계가 열렸는지 확인해요.']]);
 s('air-mass','공기 추가','넣은 공기 양','단단한 용기·밀폐·외부 물기 없음','전체 질량','적은 공기',100,'공기 추가',103,'g','용기 크기와 재료는 같습니다.',[
 ['질량 증가의 설명은?','추가한 공기도 질량이 있다','기체는 물질이 아니다|용기가 반드시 커졌다|공기는 질량이0이다','기체 존재를 질량으로 확인해요.'],['공기를 일부 빼고 다시 재면?','전체 질량이 줄 수 있다','질량이 무조건 늘어난다|용기 재료가 사라진다|기체는 저울에 영향 못 준다','물질 이동의 방향을 봐요.'],['부피 증가만 원인으로 못 보는 근거는?','단단한 같은 용기 크기를 유지했다','질량값이 정수라는 사실만|용기가 보였다는 것만|공기는 투명하다는 것만','부피를 통제했어요.']]);
 s('bottle-air','거꾸로 넣은 병','병 기울임','물통·병·넣는 깊이','병 안에 들어간 물','똑바로 거꾸로',1,'기울임',8,'mL','기울였을 때 기포가 밖으로 나왔습니다.',[
 ['처음 물이 적게 들어온 이유는?','병 속 공기가 공간을 차지했다','병 속은 완전 진공이었다|물은 아래로만 가서 영원히 못 들어간다|유리가 물을 모두 흡수했다','갇힌 기체를 생각해요.'],['기체가 더 빠져나가면?','물이 그 자리를 더 채울 수 있다','공간이 완전히 사라진다|기포가 반드시 고체다|물은 절대 못 들어간다','공간 점유를 연결해요.'],['병 안 공기의 근거는?','기울일 때 기포가 나왔다','병 색이 투명했다만|병 이름이 같았다만|물통이 컸다만','기포는 기체의 관찰 흔적이에요.']]);
 s('limewater','석회수 반응','기체 종류','같은 석회수·기체 양·시간','흐려진 정도','이산화 탄소',8,'산소',0,'눈금','지시된 조건의 성질 비교이며 흡입하지 않습니다.',[
 ['이산화 탄소 판단 근거는?','석회수를 흐리게 한 반응','기체가 투명하다는 것만|냄새를 맡은 느낌|병 크기가 같다는 것만','특징적 반응을 써요.'],['미지 기체를 비교하려면?','같은 석회수 조건으로 시험한다','석회수 양을 임의로 바꾼다|색만 보고 산소로 정한다|맛으로 확인한다','안전한 공통 시험이에요.'],['B의0이 기체 없음의 증거인가?','산소도 있어도 그 반응이 없을 수 있다','반응 없으면 언제나 진공이다|투명하면 모두 같은 기체다|산소는 물질이 아니다','특정 반응 부재와 존재는 달라요.']]);
 s('oxygen','연소 돕기','산소 공급','같은 연료·처음 온도·장치','연소 지속 시간','산소 충분',30,'공급 제한',8,'초','불 실험을 따라 하지 않는 가상 자료입니다.',[
 ['A가 긴 이유로 적절한 것은?','산소 공급이 연소를 도왔다','산소가 모든 경우 연료 자체다|기체는 연소와 무관하다|연료가 반드시 더 많았다','역할을 구별해요.'],['산소가 있어도 연료가 없으면?','그 연료의 연소는 일어날 수 없다','산소가 반드시 혼자 탄다|불꽃이 무한히 생긴다|온도는 필요 없다','연료 조건도 필요해요.'],['산소 효과만 보려면?','연료 양과 처음 상태를 맞춘다','A에만 연료를 더 넣는다|B만 식혀 둔다|장치를 다른 크기로 바꾼다','다른 연소 변인을 통제해요.']]);
 s('fill-space','기체 퍼짐','연결 통로 개방','같은 기체 양·용기·온도','기체가 감지된 칸 수','통로 닫힘',1,'통로 열림',4,'칸','같은 네칸 용기에서 한칸에 기체를 넣고 충분히 기다렸습니다.',[
 ['열림 결과의 설명은?','기체가 가능한 공간으로 퍼졌다','기체 양이 네 배로 생성됐다|입자 자체가 용기만큼 커졌다|기체가 고체 격자로 고정됐다','분포와 양을 구분해요.'],['다시 통로를 닫으면?','각 칸에 있던 기체가 남을 수 있다','모든 기체가 자동 한칸으로 돌아온다|기체가 무조건 없어진다|입자 운동이 반드시 0이다','현재 분포를 고려해요.'],['감지 칸 증가가 질량 증가를 뜻하지 않는 이유는?','같은 기체가 넓은 공간에 나뉘었다','칸 수는 질량 단위라서|닫힌 계도 입자를 계속 만들어서|기체는 질량이 없어서','양 보존과 퍼짐을 구별해요.']]);
 s('temperature-balloon','공기와 온도','온도','같은 공기 양·유연한 풍선·압력 조건','풍선 부피','차가움',80,'따뜻함',100,'mL','터지지 않는 범위이며 기체 유출이 없습니다.',[
 ['부피 증가 모형은?','같은 입자 수의 평균 간격 증가','입자 자체의 크기 증가|입자 수 자동 증가|공기 질량이 무조건 증가','물질 양은 같아요.'],['다시 차갑게 하면?','부피가 줄 수 있다','반드시 질량이 사라진다|무조건 더 커진다|항상 같은100mL다','온도 조건을 되돌려요.'],['단단한 용기에도 같은 부피 결과를 강요 못 하는 이유는?','용기 부피가 고정될 수 있다','단단한 용기엔 기체가 없어서|온도는 무관해서|모든 용기는 유연해서','용기 조건도 중요해요.']]);
 s('invisible','겉모습과 성질','기체 종류','같은 용기·조명·관찰 방법','석회수 흐림','투명 기체甲',7,'투명 기체乙',0,'눈금','둘 다 맨눈으로 구별할 색이 없었습니다.',[
 ['같은 외관으로 같은 물질이라 할 수 있나?','반응이 달라 단정할 수 없다','투명하면 반드시 동일하다|반응은 물질과 무관하다|기체는 모두 산소다','외관 외 성질을 봐요.'],['정체를 더 확인하려면?','안전한 추가 성질 자료를 비교한다','직접 흡입한다|맛을 본다|투명하니 무조건 공기라 쓴다','여러 근거가 필요해요.'],['“보이지 않으면 없다”에 대한 반례는?','두 기체가 용기를 차지하고 반응 자료를 보인다','병이 투명한 것만|밝기가 같은 것만|색 이름이 없는 것만','보이지 않는 존재를 간접 측정해요.']]);
 s('leak','기체 유출','마개 상태','같은 처음 기체·용기·시간','용기 내부 남은 기체 양','밀폐',10,'틈 있음',6,'상대량','틈 있는 용기에서는 기체가 밖으로 나갑니다.',[
 ['B의 입자 수 변화 설명은?','일부가 계 밖으로 나갔다','입자가 압축돼 작아졌다|입자 자체가 소멸했다|기체가 물질이 아니게 됐다','이동과 소멸을 구분해요.'],['기체 양 유지 실험에는?','마개 누출을 확인한다','틈을 더 만든다|부피만 기록하고 마개는 무시|매번 기체를 더 넣는다','닫힌 조건을 확보해요.'],['B를 밀폐 압축과 같은 모형으로 못 그리는 이유는?','물질 양 자체가 달라졌다','입자는 항상 수가 같아서|용기 크기는 무조건 달라서|기체에는 입자가 없어서','압축과 누출은 다른 과정이에요.']]);
 s('gas-mixture','공기 성분','성분 종류','같은 공기100칸 기준','차지하는 몫','질소',78,'산소',21,'칸','나머지 약1칸은 다른 기체이며 대략적 모형값입니다.',[
 ['공기에 대한 해석은?','여러 기체가 섞인 혼합물','순수 산소만|질소와 산소가 같은 물질|아무 물질도 없는 공간','성분과 몫을 읽어요.'],['산소만의 성질을 알아보려면?','분리된 기체 성질 자료가 필요하다','공기 전체를 순수 산소로 간주|질소가 많으니 산소는 없다|몫을 더하면 산소 이름을 안다','혼합물과 성분을 구분해요.'],['합이99인 이유의 적절한 설명은?','다른 기체 몫도 있다','나머지는 반드시 진공이다|공기가 질량을 잃었다|수치는 모든 장소에서 정확히 고정이다','대략 구성과 나머지를 봐요.']]);
 s('safety','기체와 밀폐 공간','환기 상태','같은 공간·사람 수·시간','산소 몫','환기됨',21,'환기 부족',16,'상대칸','위험 원리를 보여 주는 가상 자료이며 건강 기준 판정표가 아닙니다.',[
 ['B에서 주의할 점은?','보이지 않아도 산소 부족 위험이 있을 수 있다','색이 없으면 안전하다|냄새 없으면 산소가 충분하다|기체는 사람에게 영향이 없다','외관으로 안전을 보장 못 해요.'],['의심스러운 밀폐 공간을 보면?','들어가지 않고 안전 담당자에게 알린다','직접 들어가 숨쉬기 시험|냄새로 산소량 판단|불을 켜 확인','직접 시험하지 않아요.'],['색 관찰만으로 판단 못 하는 이유는?','산소량 차이가 색으로 드러나지 않을 수 있다','산소는 항상 붉어서|기체 색은 양과 항상 같아서|환기는 성분에 무관해서','안전에는 적절한 측정이 필요해요.']]);
